// ============================================
// FidelinvestigatorAI - Password Analyzer
// ============================================

const data = $input.first().json.extracted_data;
const analysisReport = $input.first().json.analysis_report;
const psychologicalProfile = $input.first().json.psychological_profile;
const logoPath = $input.first().json.logo_path;

// Common patterns
const commonPatterns = {
  keyboard_walk: ['qwerty', 'asdf', 'zxcv', 'qazwsx', '1qaz', '2wsx', 'qwertyuiop', 'asdfghjkl'],
  sequential_numbers: ['123', '1234', '12345', '123456', '321', '4321', '987', '654'],
  common_words: ['password', 'admin', 'user', 'login', 'welcome', 'master', 'pass', 'secret'],
  italian_words: ['ciao', 'amore', 'italia', 'roma', 'milano', 'napoli', 'casa', 'sole', 'mare', 'bella']
};

const datePatterns = [
  /\b(19|20)\d{2}\b/,
  /\b\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])\b/,
  /\b(0[1-9]|[12]\d|3[01])(0[1-9]|1[0-2])\d{2,4}\b/
];

const passwords = [...(data.raw_passwords || [])];
for (const breach of data.data_breaches || []) {
  if (breach.password_plain) passwords.push(breach.password_plain);
}
const uniquePasswords = [...new Set(passwords)];

function assessStrength(password) {
  const length = password.length;
  const hasUpper = /[A-Z]/.test(password);
  const hasLower = /[a-z]/.test(password);
  const hasNum = /\d/.test(password);
  const hasSpecial = /[!@#$%^&*(),.?":{}|<>]/.test(password);

  let charsetSize = 0;
  if (hasLower) charsetSize += 26;
  if (hasUpper) charsetSize += 26;
  if (hasNum) charsetSize += 10;
  if (hasSpecial) charsetSize += 32;

  const entropy = charsetSize > 0 ? length * Math.log2(charsetSize) : 0;

  const weaknesses = [];
  if (length < 8) weaknesses.push('Lunghezza insufficiente (< 8 caratteri)');
  if (!hasUpper) weaknesses.push('Mancanza di maiuscole');
  if (!hasLower) weaknesses.push('Mancanza di minuscole');
  if (!hasNum) weaknesses.push('Mancanza di numeri');
  if (!hasSpecial) weaknesses.push('Mancanza di caratteri speciali');

  const pwdLower = password.toLowerCase();
  for (const word of commonPatterns.common_words) {
    if (pwdLower.includes(word)) {
      weaknesses.push(`Contiene parola comune: ${word}`);
      break;
    }
  }

  const score = entropy - (weaknesses.length * 5);
  let level;
  if (score < 20) level = 'very_weak';
  else if (score < 35) level = 'weak';
  else if (score < 50) level = 'medium';
  else if (score < 65) level = 'strong';
  else level = 'very_strong';

  const masked = password.length > 2 
    ? password[0] + '*'.repeat(password.length - 2) + password[password.length - 1]
    : '*'.repeat(password.length);

  return {
    password_masked: masked,
    length,
    has_uppercase: hasUpper,
    has_lowercase: hasLower,
    has_numbers: hasNum,
    has_special: hasSpecial,
    entropy_score: Math.round(entropy * 100) / 100,
    strength_level: level,
    weaknesses
  };
}

function identifyPatterns(password) {
  const patterns = [];
  const pwdLower = password.toLowerCase();

  // Keyboard walks
  for (const walk of commonPatterns.keyboard_walk) {
    if (pwdLower.includes(walk)) {
      patterns.push({
        pattern_type: 'keyboard_walk',
        pattern_value: walk,
        description: `Sequenza tastiera: ${walk}`,
        security_impact: 'high'
      });
    }
  }

  // Sequential numbers
  for (const seq of commonPatterns.sequential_numbers) {
    if (password.includes(seq)) {
      patterns.push({
        pattern_type: 'sequential_numbers',
        pattern_value: seq,
        description: `Sequenza numerica: ${seq}`,
        security_impact: 'high'
      });
    }
  }

  // Repeated chars
  const repeatMatch = password.match(/(.)\1{2,}/);
  if (repeatMatch) {
    patterns.push({
      pattern_type: 'repeated_chars',
      pattern_value: repeatMatch[0],
      description: `Caratteri ripetuti: ${repeatMatch[0]}`,
      security_impact: 'medium'
    });
  }

  // Dates
  for (const datePattern of datePatterns) {
    const match = password.match(datePattern);
    if (match) {
      patterns.push({
        pattern_type: 'date',
        pattern_value: match[0],
        description: `Data identificata: ${match[0]}`,
        security_impact: 'high'
      });
    }
  }

  // Italian words
  for (const word of commonPatterns.italian_words) {
    if (pwdLower.includes(word)) {
      patterns.push({
        pattern_type: 'italian_word',
        pattern_value: word,
        description: `Parola italiana: ${word}`,
        security_impact: 'medium'
      });
    }
  }

  // Personal name in password
  if (data.personal_info.full_name) {
    const nameParts = data.personal_info.full_name.toLowerCase().split(' ');
    for (const part of nameParts) {
      if (part.length > 2 && pwdLower.includes(part)) {
        patterns.push({
          pattern_type: 'personal_name',
          pattern_value: part,
          description: `Contiene nome personale: ${part}`,
          security_impact: 'critical'
        });
      }
    }
  }

  // Username in password
  for (const username of data.usernames) {
    if (username.length > 2 && pwdLower.includes(username.toLowerCase())) {
      patterns.push({
        pattern_type: 'username',
        pattern_value: username,
        description: `Contiene username: ${username}`,
        security_impact: 'critical'
      });
    }
  }

  return patterns;
}

// Analyze passwords
const strengthAssessments = [];
const allPatterns = [];

for (const pwd of uniquePasswords) {
  strengthAssessments.push(assessStrength(pwd));
  allPatterns.push(...identifyPatterns(pwd));
}

// Find common elements
const commonElements = [];
if (uniquePasswords.length >= 2) {
  const allSubstrings = [];
  for (const pwd of uniquePasswords) {
    for (let i = 0; i < pwd.length; i++) {
      for (let j = i + 3; j <= pwd.length; j++) {
        allSubstrings.push(pwd.substring(i, j).toLowerCase());
      }
    }
  }

  const substringCounts = {};
  for (const substr of allSubstrings) {
    substringCounts[substr] = (substringCounts[substr] || 0) + 1;
  }

  for (const [substr, count] of Object.entries(substringCounts)) {
    if (count > 1 && substr.length >= 3) {
      commonElements.push(substr);
    }
  }
  commonElements.sort((a, b) => b.length - a.length);
}

// Construction method
const methods = [];
const patternTypes = {};
for (const p of allPatterns) {
  patternTypes[p.pattern_type] = (patternTypes[p.pattern_type] || 0) + 1;
}

if (patternTypes['personal_name']) methods.push('Utilizza informazioni personali (nome/cognome)');
if (patternTypes['date']) methods.push('Incorpora date significative');
if (patternTypes['keyboard_walk']) methods.push('Usa sequenze tastiera');
if (patternTypes['sequential_numbers']) methods.push('Aggiunge sequenze numeriche');
if (commonElements.length > 0) methods.push(`Schema base comune: ${commonElements[0]}`);

// Security score
let securityScore = 0;
if (strengthAssessments.length > 0) {
  const avgEntropy = strengthAssessments.reduce((sum, s) => sum + s.entropy_score, 0) / strengthAssessments.length;
  const criticalPatterns = allPatterns.filter(p => p.security_impact === 'critical').length;
  const highPatterns = allPatterns.filter(p => p.security_impact === 'high').length;

  securityScore = avgEntropy - (criticalPatterns * 15) - (highPatterns * 8);
  securityScore = Math.max(0, Math.min(100, securityScore));
}

let securityLevel;
if (securityScore < 20) securityLevel = 'CRITICO';
else if (securityScore < 40) securityLevel = 'BASSO';
else if (securityScore < 60) securityLevel = 'MEDIO';
else if (securityScore < 80) securityLevel = 'BUONO';
else securityLevel = 'ECCELLENTE';

// Predictions
const predictions = [];
if (commonElements.length > 0) {
  const base = commonElements[0];
  predictions.push({
    prediction_type: 'base_pattern',
    description: `Il target usa probabilmente '${base}' come base per altre password`,
    confidence: 0.7,
    examples: [`${base}123`, `${base}2024`, `${base.charAt(0).toUpperCase() + base.slice(1)}!`]
  });
}

if (data.personal_info.full_name) {
  const firstName = data.personal_info.full_name.split(' ')[0].toLowerCase();
  predictions.push({
    prediction_type: 'name_based',
    description: 'Possibile utilizzo del nome in altre password',
    confidence: 0.6,
    examples: [`${firstName}123`, `${firstName.charAt(0).toUpperCase() + firstName.slice(1)}!`]
  });
}

// Recommendations
const recommendations = [
  'Utilizzare un password manager per generare e gestire password uniche',
  'Abilitare autenticazione a due fattori (2FA) su tutti gli account'
];

if (strengthAssessments.some(s => ['very_weak', 'weak'].includes(s.strength_level))) {
  recommendations.push('Aumentare la lunghezza delle password a minimo 12-16 caratteri');
}
if (patternTypes['personal_name']) {
  recommendations.push('Evitare uso di informazioni personali nelle password');
}
if (patternTypes['date']) {
  recommendations.push('Non utilizzare date significative nelle password');
}
if (commonElements.length > 0) {
  recommendations.push('Evitare di riutilizzare la stessa base per multiple password');
}
recommendations.push('Cambiare immediatamente tutte le password compromesse');

// Psychological insights
const psychologicalInsights = [];
if (strengthAssessments.length > 0) {
  const avgLength = strengthAssessments.reduce((sum, s) => sum + s.length, 0) / strengthAssessments.length;
  if (avgLength < 8) {
    psychologicalInsights.push('Preferenza per password corte suggerisce priorità alla comodità rispetto alla sicurezza.');
  } else if (avgLength > 12) {
    psychologicalInsights.push('Uso di password lunghe indica consapevolezza della sicurezza.');
  }
}

if (patternTypes['personal_name'] || patternTypes['date']) {
  psychologicalInsights.push('Incorporazione di dati personali riflette legame emotivo con queste informazioni.');
}
if (commonElements.length > 0) {
  psychologicalInsights.push('Presenza di elementi comuni suggerisce approccio sistematico alla creazione password.');
}
if (data.data_breaches.length > 1) {
  psychologicalInsights.push('Coinvolgimento in multipli breach suggerisce inerzia nella gestione credenziali.');
}

const passwordProfile = {
  passwords_analyzed: uniquePasswords.length,
  patterns: allPatterns,
  strength_assessments: strengthAssessments,
  common_elements: commonElements.slice(0, 5),
  construction_method: methods.join('; ') || 'Non determinabile',
  security_score: Math.round(securityScore),
  security_level: uniquePasswords.length > 0 ? securityLevel : 'SCONOSCIUTO',
  predictions,
  recommendations,
  psychological_insights: psychologicalInsights
};

return {
  json: {
    extracted_data: data,
    analysis_report: analysisReport,
    psychological_profile: psychologicalProfile,
    password_profile: passwordProfile,
    logo_path: logoPath
  }
};

