const weaknesses = [];
const immediateActions = [];

for (const vuln of vulnerabilities) {
  if (vuln.severity === 'critical') {
    score -= 25;
    weaknesses.push(vuln.description);
    immediateActions.push(vuln.remediation);
  } else if (vuln.severity === 'high') {
    score -= 15;
    weaknesses.push(vuln.description);
  } else if (vuln.severity === 'medium') {
    score -= 8;
  }
}

for (const metric of exposureMetrics) {
  if (metric.risk_level === 'critical') score -= 15;
  else if (metric.risk_level === 'danger') score -= 10;
  else if (metric.risk_level === 'warning') score -= 5;
}

if (data.raw_passwords.length === 0) {
  score += 10;
  strengths.push('Nessuna password esposta in chiaro');
}
if (data.data_breaches.length === 0) {
  score += 15;
  strengths.push('Nessun coinvolgimento in data breach noti');
}
if (data.social_media.length <= 3) {
  score += 5;
  strengths.push('Presenza social contenuta');
}

score = Math.max(0, Math.min(100, score));

let grade;
if (score >= 90) grade = 'A';
else if (score >= 80) grade = 'B';
else if (score >= 70) grade = 'C';
else if (score >= 50) grade = 'D';
else grade = 'F';

const securityPosture = {
  overall_score: Math.round(score),
  grade,
  strengths,
  weaknesses: weaknesses.slice(0, 5),
  immediate_actions: immediateActions.slice(0, 3)
};

// Privacy score
let privacyScore = 100;
if (data.personal_info.full_name) privacyScore -= 10;
if (data.personal_info.date_of_birth) privacyScore -= 15;
privacyScore -= data.contact_info.emails.length * 5;
privacyScore -= data.contact_info.phones.length * 10;
privacyScore -= data.social_media.length * 3;
privacyScore -= data.locations.length * 5;
privacyScore = Math.max(0, privacyScore);

// Prioritized recommendations
const recommendationsPriority = [];

if (data.raw_passwords.length > 0) {
